int biggest_Component(Graph g)
{
    int w, count, max;
    Queue q;
    q.head = NULL;
    q.size = 0;
    q.tail = NULL;
    for (int j=1; j<g.V;j++)
    {
        enqueue(&q, j);
        g.visited[j-1] = 1;
        count = 1;
        while (isEmptyQueue(q) == 0)
        {
            w = dequeue(&q);
            for (int i; i<g.V; i++)
            {
                if (g.matrix[w-1][i] == 1 && g.visited[i] == 0)
                {
                    count++;
                    g.visited[i] = 1;
                    enqueue(&q, i+1);
                }
            }
        }
        if (j==0)
        {
            max = count;
        }
        else if (count > max)
        {
            max = count;
        }
    }
    return max;
}

