    // count the number of nodes in longest component

    Queue q;
    q.head = NULL;
    q.size = 0;
    q.tail = NULL;

    enqueue(&q, g.V);
    g.visited[g.V] = 1;

    int topqueue;
    int i;
    int counta = 0 ;
    int countb = 0;

    while(!isEmptyQueue(q)){

        topqueue = dequeue(&q);

        for(i=0; i<g.V;i++){
            if(g.matrix[topqueue][i] == 1 && g.visited[i] == 0){
                g.visited[i] = 1;
                enqueue(&q, i);
                counta = counta+1;
                break;
            }
        }
    }

    int vertex = ((g.V) - counta);

    enqueue(&q, vertex);

    while(!isEmptyQueue(q)){

        topqueue = dequeue(&q);

        for(i=0; i<g.V;i++){
            if(g.matrix[topqueue][i] == 1 && g.visited[i] == 0){
                g.visited[i] = 1;
                enqueue(&q, i);
                counta = countb+1;
                break;
            }
        }

    }


    if(counta > countb){
        return counta;
    }
    else{
        return countb;
    }
}


