int F(int n, int k)
{	int i,j;
    int *M;
    M = (int *)malloc(sizeof(int));
    while(n>=0 && k>0){
        M[n,0]=1;
        M[0,k]=0;
    }

    for(i=0;i<6;i++){
        for(j=1;j<6;j++){
            M[i,j]=M[i-1,j-1]+M[i-1,j];
        return M[n,k];
        }
    }            
}

