int BFS(Graph g,int v){
    Queue q;
    enqueue(&q, v);
    int count = 1;
    g.visited[v] = 1;

    while(!isEmptyQueue(q)){
        int w = dequeue(&q);
        for(int i=0;i<g.V;i++){
            if(g.visited[i] == 0 && g.matrix[w][i] == 1){
                g.visited[i] = 1;
                enqueue(&q, i);
                count++;
            }
        }
    }

    return count;
}

int biggest_Component(Graph g){
    int count = 0;
    for(int i=1;i<g.V+1;i++){

        if(BFS(g, i) <= BFS(g, i+1)){
            count = BFS(g, i+1);
        }

        else{
            count = BFS(g, i);
        }

    }

    return count;
}


