int dp(int n)
{
    //dynamic programming function to calculate F(n)
    int F[n];
    F[0] = 0;
    F[1] = 1;
    F[2] = 2;
    int result;

    for(int i=0; i<n; i++) {
        F[i] = -1;
    }

    if(n < 0){
        return -1;
    }

    if(n == 0){
        F[0] = 0;
        result = 0;
        return result;
    }

    if(n == 1){
        F[1] = 1;
        result = 1;
        return result;
    }

    if(n == 2){
        F[2] = 2;
        result = 2;
        return 2;
    }

     if(n >= 3){
        if(F[n-1] == -1){
            return dp(n-1) + dp(n-2) - 2 * dp(n-3);
        }else if(F[n-2] == -1){
            return dp(n-2) + dp(n-3) - 2 * dp(n-4);
        }else if(F[n-3] == -1){
            return dp(n-3) + dp(n-4) - 2 * dp(n-5);
        }
    }



    F[n] = (F[n-1] + F[n-2]) - (2 * F[n-3]);
    return F[n];

}

