int biggest_Component(Graph g)
{
    // count the number of nodes in longest component
    int nodecount[g.V];
    for (int i=0;i<g.V;i++) //count nodes in all vertices then store into node count array
    {
        nodecount[i]=BFS(g,i);
    }
    int max = 0;
    for (int i=0;i<g.V;i++)
    {
        if (nodecount[i]>max)
        {
            max=nodecount[i];
        }
    }
    return max;

}
int BFS (Graph g,int count) // count nodes in graph given node count
{
    Queue q, *qptr;
    q.head=NULL;
    q.size=0;
    q.tail=NULL;
    qptr = &q;
    enqueue(qptr, count);
    int counter=1;
    int visiting =0;
    while (isEmptyQueue(q)!=1)
    {
        visiting = dequeue(qptr);
        g.visited[visiting] = 1;
        for (int i = 0; i<g.V; i++)
        {
            if (g.matrix[visiting][i] == 1 && g.visited[i] ==0)
            {
                enqueue(qptr,i);
                counter++;
            }
        }
    }
    return counter;
}


