int dp(int n)
{
    //dynamic programming function to calculate F(n)

    int i;
    int *F;
    F = malloc(sizeof(int));
    for(i=0;i<n+3;i++){
       F[i]=0;
}
    //F[n+3] = malloc(sizeof(int)*(n+3));

    F[1] = 1;
    F[0] = 0;
    F[2] = 2;
    for(i=3;i<n;i++){
    F[i] = F[i-1]+F[i-2]-2*F[i-3];}
    return F[n];
}

