int survivor(int N,int M,int R,int C,int S){
  //write your code here
  int pos[][];
  for(int i=1;i<=N;i++)
  {
    for(int j=1;j<=M;j++)
    {
      pos=pos[i][j];
    }
  }
  int danger[][];
  for(int k=R;k>=R-2||k<=R+2;k--,k++)
  {
    for(int l=C;l>=C||l<=R+2;l--,l++)
    {
      danger=danger[k][l];
      danger-=danger[k-2][l-2] && danger[k+2][l+2];
    }
  }
   move(pos,danger,N,M)
}
int move(int p, int d, int r, int c)
{
  for(int i=1;i<=r;i++)
  {
    for(int j=1;j<=c;j++)
    {
      p[i][j]=p[i][i+1]||p[j+1][j];
      while(p[i][j]==d[i][j])
      {
        if(p[i][j]==[p[r][c])
        {
          return 1;
        }
        else 
        {
          return 0;
        }
      }
    }
  }
}

