int biggest_Component(Graph g){
    // count the number of nodes in longest component
    // initialise queue
    Queue q;
    q.head=q.tail=NULL;
    q.size=0;

    //mark all nodes as unvisited
    for (int i;i<g.V;i++)
        {
            g.visited[i]=0;
        }

    enqueue(&q,g.V);
    g.visited[0]=1;
    int count=1;

    while (!isEmptyQueue(q))
    {
        int cur= dequeue(&q);
        for (int i=0;i<g.V;i++)
        {
            if(g.matrix[cur-1][i]==1 && g.visited[i]==0)  
                {
                    g.visited[i]=1;
                    enqueue(&q,i+1);
                    count++;
                }
        }
    }

    return count+1;
}


