int isCyclic(Graph g)
{
    int visited[g.V];
    for (int i=0;i<g.V;i++){
        for (int j=0;j<g.V;j++){
            visited[j]=0;
        }
        int cyclic = 0;
        Stack s;
        s.size=0;
        s.head=NULL;
        int v = i+1;
        push (&s,v);
        visited[v-1]=1;
        while (!isEmptyStack(s)){
            int foundunvisited = 0;
            int w = peek(s);

            if (w == v) cyclic++;

            ListNode *cur = g.list[w-1];
            while (cur){
                int u = cur->vertex;
                if (visited[u-1] == 0){
                    foundunvisited = 1;
                    push(&s,u);
                    visited[u-1]=1;
                }
                cur = cur->next;
            }
            if (!foundunvisited) pop(&s);

        }
        if (cyclic >= 2) return 1;
        
    }
    return 0;
}



