int BFS(Graph g, int v)
{
    Queue q;
    q.head = q.tail = NULL;
    q.size = 0;

    int count = 0;

    enqueue(&q, v);
    g.visited[v] = 1;

    while(isEmptyQueue(q))
    {
        int w = dequeue(&q);
        for(int i = 0; i < g.V; i++)
        {
            if(g.matrix[w][i] == 1 && g.visited[i] == 0)
            {
                g.visited[i] = 1;
                count++;
                enqueue(&q, i);
            }
        }
    }

    return count;
}


