int nQueensAll(int** board, int BSize, int col)
{
    int i,j,k,l, queens;

    if (BSize == 0) return 0;
    if (BSize == 1) count = 1;

    board[0][0] = 1;

    for (i=0; i<BSize; i++)
    {
        for (j=0; j<BSize; j++)
        {
            board[i][j] = 1;

            if (!isSafe(board, BSize, i, j))
            {
                board[i][j] = 0;
            }

            else
            {
                if (col<BSize-1)
                {
                    count = count + nQueensAll(board, BSize, col+1);
                }

                for (k=0; k<BSize; k++)
                {
                    for(l=0; l<BSize; l++)
                    {
                        if (board[k][l] == 1) queens++;
                    }
                }
                if (queens == BSize) count++;

                for (k=i; k<BSize; k++)
                {
                    for(l=j; l<BSize; l++) board [k][l] = 0;
                }
            }
        }
    }
    return count;
}

