    memo[i,0] = 1; 
    memo[0,j] = 0;
    return 0;    
}



int F(int n, int k)
{	
    if(memo[n]== 0 && memo[k] == 0)
    {
        if(n <= 1 && k <= 1 )
        {
            memo[n] = n;
            memo[k] = k;
        }
        else
        {
         memo[n,k] = F(n-1,k-1) + F(n-1,k);   

        }
    }
    return memo[n,k];



}

