int dp(int n)
{
    //dynamic programming function to calculate F(n)
    if (n==15)
        return 59;
    else if (n==14)
        return 46;
    else if (n==13)
        return 27;
    else if (n==12)
        return 7;
    else if (n==11)
        return -6;
    else if (n==10)
        return -13;
    else if (n==9)
        return -13;
    else if (n==8)
        return -10;
    else if (n==7)
        return -5;
    else if (n==6)
        return -1;
    else if (n==5)
        return 2;
    else if (n==4)
        return 3;
    else if (n==3)
        return 3;
    else if (n==2)
        return 2;
    else if (n==1)
        return 1;
    else if (n==0)
        return 0;
    else
        {
            int f = (dp(n-1) + dp(n-2) - 2*dp(n-3));
            return f;
        }
}

