int F(int n, int k)
{	

    if(n>=0)
    {
        for(int i = 0; i <= n; i++)
        {
            dp[i][0] = 1;
        }
    }

    if(k>0)
    {
        for(int i = 1; i <= n; i++)
        {
            dp[0][i] = 0;
        }
    }

    if(dp[n][k] != -1)
            return dp[n][k];

    int temp = 0;
    for(int i=1;i<=n;i++)
    {
        for(int j=1;j<=k;j++)
       {
        dp[i][j] = F(i-1, j-1) + F(i-1, j);
        temp = dp[i][j];
       }

    }

return temp;

}

