int isCyclic(Graph g)
{
    int *visited = (int *) malloc(sizeof(int) * g.V);

    for (int j = 0; j < g.V; j++)
    {
        for (int i = 0; i < g.V; i++) visited[i] = 0;

        Queue q;
        q.head = NULL;
        q.tail = NULL;
        q.size = 0;

        enqueue(&q, j);
        visited[j]++;
        ListNode *ln;

        int w, u;
        while (!isEmptyQueue(q))
        {
            w = dequeue(&q);
            ln = g.list[w];

            for (; ln != NULL; )
            {
                u = ln->vertex;
                visited[u]++;
                if (visited[u] < 1)
                {
                    enqueue(&q, u);
                }
                ln = ln->next;
            }
        }

        // printf("\n %d ->", j);
