int biggest_Component(Graph g){
    // count the number of nodes in longest component
    int count = 1, max_count = 0, v = 1;

    // Initialize queue
    Queue q;
    q.head = NULL;
    q.tail = NULL;
    q.size = 0;

    // Enqueue v into q and mark v as visited
    enqueue(&q, v);
    g.visited[v-1] = 1;

    // while q is not empty
    while(!isEmptyQueue(q))
    {
        // dequeue vertex w
        int w = dequeue(&q);
        for(int u = 0; u<g.V;u++){
            if(g.matrix[w-1][u] == 1 && g.visited[u] == 0){
                g.visited[u] = 1;
                count++;
                enqueue(&q, u);
            }
        }
    }

    if(max_count < count)
        max_count = count;
    count = 1;

    // Check if visited all nodes
    for(int i = 1;i<=g.V;i++){
        if(g.visited[i] == 0){
            // Enqueue v into q and mark v as visited
            enqueue(&q, i);
            g.visited[i-1] = 1;

            // while q is not empty
            while(!isEmptyQueue(q))
            {
                // dequeue vertex w
                int w = dequeue(&q);
                for(int u = 0; u<g.V;u++){
                    if(g.matrix[w-1][u] == 1 && g.visited[u] == 0){
                        g.visited[u] = 1;
                        count++;
                        enqueue(&q, u);
                    }
                }
            }

            if(max_count < count)
                max_count = count;
            count = 1;
        }
    }

    return max_count;
}


