int biggest_Component(Graph g){
    // count the number of nodes in longest component
    Queue q;
    q.head = NULL;
    q.tail = NULL;
    q.size = 0; 
    int count =0;
    int visit = 1;
    int temp = 0;
    if (g.V == 0) return 0;
    enqueue(&q, 1);
    g.visited[0] = 1;
    while (visit != g.V){
        while (!isEmptyQueue(q)){
            int k = dequeue(&q);
            count++;
            for (int i =0; i<g.V; i++){
                if (g.matrix[k-1][i] && !g.visited[i]){
                    g.visited[i] = 1;
                    visit ++;
                    enqueue(&q, i+1);
                }
            }
        }
        if (count > temp) temp = count;
        for (int j = 0; j<g.V;j++){
            if (!g.visited[j]){
                g.visited[j] = 1;
                enqueue(&q, j+1);
                visit++;
            }

        }
    }
    return temp;
}


