    Queue q;
    q.head = NULL;
    q.tail = NULL;
    q.size = 0;

    enqueue(&q,0);
    g.visited[0] = 1;

    int found = 0;
    for(int i = 0; i <g.V; i++){
        g.visited[i] = 0;
    }

    while(!isEmptyQueue(q)){
        int w = dequeue(&q);
        for(int u = 0; u <g.V; u++){
            if (g.matrix[w][u] == 1 && g.visited[u] == 0) {
                g.visited[u] == 1;
                enqueue(&q, u);
                found++;
            }
        }
    }

    for(int i = 0; i <g.V; i++){
        g.visited[i] = 0;
    }
    return found;
}


