int isCyclic(Graph g)
{
    ListNode *temp;
    
    // Initialise queue
    Stack s;
    s.size = 0;
    s.head = NULL;

    // Array to keep track of visited nodes
    int visited[g.V];

    for (int i=1; i<=g.V; i++) {
        // Reset visited array
        for (int j=0; j<g.V; j++) {
            visited[j] = 0;
        }

        // Clear stack
        removeAllItemsFromStack(&s);

        // Push first node
        push(&s, i);
        visited[i-1] = 1;

        // DFS
        int count = 0;
        while (!isEmptyStack(s)) {
            int w = peek(s);

            // Push an unvisited vertex adjacent to w
            temp = g.list[w-1];
            if (temp->next != NULL) {
                temp = temp->next;
                push(&s, temp->vertex);
                count++;
            }
            else {
                pop(&s);
            }

            if (temp->vertex == i && count>2) {
                return 1;
            }
        }
    }

    return 0;
}



