int dp(int n)
{
    if (n == 0) return 0;
    if (n == 1) return 1;
    if (n == 2) return 2;

    int n1 = dp(n-2);
    int n2 = dp(n-1);
    int n3 = dp(n-3);

    return 2 * n1 - n2 - n3;
}

