int isCyclic(Graph g)
{
    ListNode *temp;
    int visited[g.V],item;
    for(int i = 0; i < g.V; i++){
        visited[i] = 0;
    }
    Queue q;
    q.head = NULL;
    q.size = 0;
    q.tail = NULL;
    for(int i = 0 ; i < g.V; i++){
        enqueue(&q, i+1);
        visited[i] = 1;
        while(!isEmptyQueue(q)){
            item = dequeue(&q);
            temp = g.list[item - 1]->next;
            while(temp!= NULL){
                if(visited[temp->vertex - 1] == 0){
                    enqueue(&q, temp->vertex);
                    visited[temp->vertex - 1] = 1;
                }
                temp = temp->next;
            }
        }
        for(int k = 0; k < g.V; k++){
            if(visited[i] == 0){
                return 0;
            }
            visited[i] = 0;
        }
    }
    return 0;
}



