    Queue Q;
    Q.head = NULL;
    Q.tail = NULL;
    Q.size = 0;
    int count;



    for (int i = 0; i < g.V; i++) {
        for (int j = 0; j < g.V; j++) {
            g.visited[i] = 1;
        }
        count = 1;
        enqueue(&Q, 0);
        g.visited[0] = 1;

        while (!isEmptyQueue(Q)) {
            int w = dequeue(i);

            for (int u = 0; u < g.V; u++) {
                if (g.matrix[w - 1][u] == 1 && g.visited[u] == 0) {
                    enqueue(&Q, u);
                    g.visited[u] == 1;
                    return;
                }
                count ++;
            }
        }
    }
    return count;
}


