int isCyclic(Graph g)
{
 int *visited;
    visited = (int *) malloc(sizeof(int)*g.V);
    int i,j, vertex, isAdj, adjV;
    for(i=0;i<g.V;i++) visited[i] = 0;
    Stack temp;
    ListNode *temp1;
    temp.head = NULL;
    temp.size = 0;
    Queue adjtoOrg;
    adjtoOrg.head = NULL;
    adjtoOrg.size = 0;
    adjtoOrg.tail = NULL;
    for(i=0;i<g.V;i++){
        push(&temp, i+1);
        visited[i] = 1;
        temp1 = g.list[i];
        while(temp1!=NULL){
                enqueue(&adjtoOrg, temp1->vertex);
                temp1 = temp1->next;
        }
        while(!isEmptyStack(temp)){
            vertex = peek(temp);
            temp1 = g.list[vertex-1];
            isAdj = 0;
            while(temp1!=NULL){
                if(visited[(temp1->vertex)-1]==0) {isAdj = 1; adjV = temp1->vertex; break;}
                temp1 = temp1->next;
            }
            if(!isAdj) pop(&temp);
            else{
                int tempVer;
                int tempSize = adjtoOrg.size;
                int *tempStore;
                int w = 0;
                tempStore = (int *) malloc(sizeof(int)*tempSize);
                while(!isEmptyQueue(adjtoOrg)){
                    tempVer = dequeue(&adjtoOrg);
                    tempStore[w] = tempVer;
                    if(tempVer == adjV) return 1;
                }
                for(j=0;j<tempSize;j++){
                    enqueue(&adjtoOrg, tempStore[j]);
                }
                push(&temp, adjV);
                visited[adjV-1] = 1;
            }
        }
        removeAllItemsFromQueue(&adjtoOrg);
        removeAllItemsFromStack(&temp);
    }

    return 0;
}



