        for (j = 0; j < V; j++)
             scanf("%d",&graph[i][j]);


    // Initialize all color values as 0.
    for (i = 0; i < V; i++)
        color[i] = 0;

    graphColoring(graph, m, color, 0);

    printf("There is/are total %d solution(s)", count);
    return 0;
}

