int dp(int n)
{
    int M[n];
    if(n==0){
        return 0;
    }
    if(n==1){
        return 1;
    }
    if(M[n-1] == -1){
        M[n-1] = dp(n-1);
    }
    if(M[n-2] ==  -1){
        M[n-1] = dp(n-1);
    }

    M[n] = M[n-1] + M[n-2];
    return M[n];
    //dynamic programming function to calculate F(n)
}

