int bfs(Graph g, int index) {
    Queue q;
    q.head=NULL;
    q.size=0;
    enqueue(&q, index+1);     // enq start vertex
    g.visited[index]=1;

    int count=0;
    while (!isEmptyQueue(q)) {
        int value = dequeue(&q);
        count++;
        for (int i=0; i<g.V; i++) {
            if (g.matrix[value-1][i] ==1 && g.visited[i]==0) {
                g.visited[i]=1;
                enqueue(&q, i);
            }
        }
    }
    return count;
}

