int isCyclic(Graph g)
{
    int i,j,w,k=1,f;
    ListNode * temp;
    Stack s;
    s.head = NULL;
    s.size = 0;
    int *store;

    return 0;

    for(i=1; i<g.V; i++){
        k=1;
        store[0]=i;
        push(&s, i);
        while (!isEmptyStack(s)){
            w = peek(s);

            if(g.list[w-1]->next == NULL){
                pop(&s);
            }

            temp = g.list[w-1]->next;
            j = temp->vertex;
            for(f=0; f<k; f++){
                if(store[f]==j){
                    j = g.list[j-1]->next->vertex;
                    break;
                }
            }
            push(&s, j);

            if(g.list[j-1]->next == NULL){
                pop(&s);
            }
            else{
                store[k] = w;
                k++;
                w = j;
            }
            return 1;
        }
        return 1; 
    }
    return 0;
}



