int biggest_Component(Graph g){
    // count the number of nodes in longest component
    int i;
    int *distance;
    distance = malloc(sizeof(int));
    for(i=0;i<g.V;i++){
        distance[i]=0;
    }


    for(i=0;i<g.V;i++){

        g.visited[i]=1;
        for(int j=0;j<g.V;j++){
            if(g.matrix[i][j]==1 && g.visited[j]==0){
                if(g.matrix[i][i-1]==1){
                distance[j]=distance[i]+1;}
                g.visited[j]=1;
            }

        }

    }

}


