int dp(int n)
{
    int total = 0;
    if (n == 0){
        total = 0;
        return 0;
    }

    if (n==1){
        total = 1;
        return 1;
    }

    if (n==2){
        total = 2;
        return 2;
    }
    int *listf;
    listf = (int*)malloc(sizeof(int));

    if (listf[n]>1){
        return total;
    }

    else  {
        if (n>=3){
        total = dp(n-1) + dp(n-2) - 2*(dp(n-3))-1;
        listf[n] = total;
        return total;
        }
    }
    listf[n] = total;
}

