int BFS(Graph g,int v){
    Queue q;
    enqueue(&q,v);
    g.visited[v-1]=1;
    int count=0;
    while(!isEmptyQueue(q)){
        int w=getFront(q);
        dequeue(&q);
        for(int i=0;i<v;i++){
            if(g.matrix[w-1][i]==1&&g.visited[i]==0){
                g.visited[i]=1;
                enqueue(&q,i+1);
            }
        }count++;
    }return count;
}

int biggest_Component(Graph g){
    // count the number of nodes in longest component
    int v=g.V;
    int count=BFS(g,v);
    if(count<v-count) return v-count;
    else return count;
}


