//Safe checking
int isSafe(int** board,int BSize, int row, int col)
{
    int i, j;
    i = row;
    j = col;

    if(i==0||j==0)
    {
        return 0;
    }
    if(i==1 && j==1)
    {
        return 0;
    }
    if(i==2 && j==2)
    {
        return 0;
    }
    if(i==3 && j==3)
    {
        return 0;
    }
    if(i==4 && j==4)
    {
        return 0;
    }
    if(i==5 && j==5)
    {
        return 0;
    }
    if(i==6 && j==6)
    {
        return 0;
    }
    if(i==7 && j==7)
    {
        return 0;
    }


    // Horicatal check
    for (i = 0; i < col; i++)
        if (board[row][i])
            return 0;

    // Upper left diagonal check
    for (i = row, j = col; i >= 0 && j >= 0; i--, j--)
        if (board[i][j])
            return 0;

    // Lower left diagonal check
    for (i = row, j = col; j >= 0 && i < BSize; i++, j--)
        if (board[i][j])
            return 0;

    return 1;
}

