int dp(int n)
{
        int*F = (int*)malloc(sizeof(int)*n);
        for(int i=0;i<=n-1;i++){
            F[i] = -1;
        }
        if(n == 0){
            return 0;
        }
        if(n == 1){
            return 1;
        }
        if(n == 2){
            return 2;
        }
        if(F[n-1] == -1){
            F[n-1] = dp(n-1);
        }
        if(F[n-2] == -1){
            F[n-2] = dp(n-2);
        }

        if(F[n-3] == -1){
            F[n-3] = dp(n-3);
        }

        F[n] = F[n-1] + F[n-2] - (2*F[n-3]) ;
        return F[n];
}

