int dp(int n,int **memoitable)
{
    //dynamic programming function to calculate F(n)
    int counter;
    if (n==0) return 0;
    if (n==1) return 1;
    if (n==2) return 2;
    if (memoitable[n-1]!=NULL)
    {
        return memoitable[n-1];
    }
    if (memoitable[n-1]==NULL)
    {
        int v1,v2,v3;
        //v1 = dp(n-1,memoitable);
        //v2 = dp(n-2,memoitable);
        //v3 = dp(n-3,memoitable);
        counter = dp(n-1,memoitable)+dp(n-2,memoitable)-2*dp(n-3,memoitable);
        memoitable[n]=counter;
        return counter;
    }
}

