{
    //dynamic programming function to calculate F(n)
    int arr[n];
    for(int i=0; i<n; i++){
        arr[i] = INT_MIN;
    }



    int p;
    int q;

    for(int i=0; i<n; i++){
        if(arr[i]==0){
