int F(int n, int k)
{	
if (n==0)&&(k>0){ 
    F(n,k)==0;
    return 0; 
}
if (n>=0)&&(k=0){
    F(n,k) == 1; 
    return 1; 
}
for (n-k)==0{
    F(n,k)==F(n-1,k-1);
    F(n,k) == F(n-1,k);
    F(n,k) == F(n-1,k-1) + F(n-1,k); 
    return F(n,k);
}
}

