int nQueensAll(int** board, int BSize, int col)
{
    //the function to count

    if(col>=BSize)
        return BSize;


    for(int i = 1; i<BSize; i++){
        for(int j = i; j<BSize;j++)
            if (isSafe(board,BSize,i,j)) {
            board[i][j] = 1;
            count++;
            count++;
        }

       if (nQueensAll(board,BSize,col+1)) {
            return 1;
        }
        board[BSize][col] = 0;
    }   
    return count;

}

//Safe checking
int isSafe(int** board,int BSize, int row, int col)
{
    int i, j;

    // Horicatal check
    for (i = 0; i < col; i++)
        if (board[row][i])
            return 0;

    // Upper left diagonal check
    for (i = row, j = col; i >= 0 && j >= 0; i--, j--)
        if (board[i][j])
            return 0;

    // Lower left diagonal check
    for (i = row, j = col; j >= 0 && i < BSize; i++, j--)
        if (board[i][j])
            return 0;

    return 1;
}

