int isCyclic(Graph g)
{
    if (g.V==0){
        return 0;
    }
    Stack s;
    s.head = NULL;
    s.size = 0;
    int visited[g.V];
    for (int i=0; i<g.V; i++){
        visited[i] = 0;
    }

    ListNode *curr;
    push(&s, 0);
    visited[0] = 1;
    while (!isEmptyStack(s)){
        int w = peek(s);
        curr = g.list[w+1]->next;
        while (curr!=NULL){
            if (visited[(curr->vertex)-1]==0){
                push(&s,(curr->vertex)-1);
                visited[(curr->vertex)-1] = 1;
            }
            curr = curr->next;
        }
        pop(&s);
    }

    for (int i=0; i<g.V; i++){
        if (visited[i] == 0){
            return 0;
        }
    }
    return 1;
}



