int dp(int n)
{    
    //dynamic programming function to calculate F(n)

    if(n<0)
        return -1;

    fn = (int*)malloc(sizeof(int)*n);
    for(int i = 3; i<n; i++){
        fn[i] = -1;
    }

    fn[0] = 0;
    fn[1] = 1;
    fn[2] = 2;


    if (fn[n-1]==-1)
        fn[n-1] = dp(n-1);

    if (fn[n-2]==-1)
        fn[n-2] = dp(n-2);

    if (fn[n-3]==-1)
        fn[n-3] = dp(n-3);

    fn[n] = fn[n-1] + fn[n-2] - 2*fn[n-3];
    return fn[n];
}

