int dp(int n)
{
    int dp[n];
    dp[0]=0;
    dp[1]=1;
    dp[2]=2;

    if (n==0)
        return 0;
    if (n==1)
        return 1;
    if (n==2)
        return 2;

    for (int i=3;i<=n;i++){
    dp[i]=2*dp[n-2]-dp[n-1]-dp[n-3];
    }
    return dp[n-1];
}

