    Stack s;
    s.head = NULL;
    s.size = 0;

    

    
    int* explored = (int*) malloc(g.V * sizeof(int));
    for (int i = 0; i < g.V; i++)
    {
        explored[i] = 0;
    }


    push(&s, g.list[0]->vertex);         // push starting node into stack
    explored[0] = 1;

    while(!isEmptyStack(s))
    {
        
        int temp = peek(s);               // peek stack 
        if (g.list[temp]->next != NULL)   // has adj
            {
                if (explored[g.list[temp]->next->vertex] == 1)
                    return 1;
                if (explored[g.list[temp]->vertex] == 1)
                    return 1;
                push(&s, g.list[temp]->next->vertex);
                explored[g.list[temp]->next->vertex] = 1;
                break;
            }
        else
        {
            pop(&s);
            explored[g.list[temp]->vertex] = 0;
        }
    
    }
    
    return 0;
    



