    }

    enqueue(s, 0);
    visited[0] = 1;

    while(!isEmptyQueue(*s)){
        cur = dequeue(s);

        temp = g.list[cur];
        while(temp != NULL){
            if((temp->vertex) - 1 == cur){
                return 1;
            }

            else if(!visited[(temp->vertex) - 1 ]){
                enqueue(s, (temp->vertex) - 1);
                visited[(temp->vertex) -1 ] = 1;
                unvisited = 0;            
            }
            temp = temp->next;
        }

    }
    return 1;
}



