int main ()
{
    int n;
    printf("Enter the value of n:\n");
    scanf("%d",&n);

    result = malloc(sizeof(int));
    for(int i=0;i<n; i++){
        result[i] = -1;
    }

    printf("The value of F(%d) is: %d \n", n, dp(n));
    return 0;
}
int dp(int n)
{
    //dynamic programming function to calculate F(n)
    if(n == 0){
        result[0] = 0;
    }
    if(n == 1){
        result[1] = 1;
    }
    if(n == 2){
        result[2] = 2;
    }


    if(result[n-1] == -1)
        result[n-1] = dp(n-1);
    if(result[n-2 == -1])
        result[n-2] = dp(n-2);
    if(result[n-3] == -1){
        result[n-3] == dp(n-3);
    }

    return result[n] = dp(n-1) + dp(n-2) -2 * dp(n-3);
}

