{
    //dynamic programming function to calculate F(n)
    //int value = 0;
    if(n==0)
        return 0;
    if(n==1)
        return 1;
    if(n==2)
        return 2;
    if (n==3)
        return 3;
    else
    {
        int value = dp(n-1)+dp(n-2)-2*dp(n-3);
        return value;
    }
}

