int dp(int n)
{
    //dynamic programming function to calculate F(n)

    int i;
    int *F;
    F = malloc(sizeof(int));
    for(i=0;i<n+3;i++){
       F[i]=0;
}
    //F[n+3] = malloc(sizeof(int)*(n+3));

    F[1] = 1;
    F[0] = 0;
    F[2] = 2;
    for(i=3;i<n;i++){
    F[i] = F[i-1]+F[i-2]-2*F[i-3];}
    return F[n];
}

from typing import Tuple

class FloydWarshall:
    """ワーシャルフロイド法"""
    def __init__(self, N:int=0, inf: int = 10**18):
        """ワーシャルフロイド法データ初期化（ノード数Nを指定）"""
        self.INF = inf
        self.N = N
        self.dist = [[inf] * N for _ in range(N)]

    def addEdge(self, src, dst, weight):
        """辺の追加（距離の更新は行わない）"""
        assert src < self.N
        assert dst < self.N
        self.dist[src][dst] = min(self.dist[src][dst], weight)

    def calcDist(self):
        """距離の計算"""
        for k in range(self.N):
            self.dist[k][k] = 0
            for i in range(self.N):
                for j in range(self.N):
                    self.dist[i][j] = min(self.dist[i][j], self.dist[i][k] + self.dist[k][j])

    def update(self, src, dst, weight):
        """辺の追加（距離の更新を行う）"""
        assert src < self.N
        assert dst < self.N
        self.dist[src][dst] = min(self.dist[src][dst], weight)
        for i in range(self.N):
            for j in range(self.N):
                self.dist[i][j] = min(self.dist[i][j], self.dist[i][src] + weight + self.dist[dst][j])

    def getResult(self):
        """答え取得"""
        result = 0
        for i in range(self.N-1):
            for j in range(self.N-1):
                if self.dist[i][j] < self.INF:
                    result += self.dist[i][j]
        return result

