int dp(int n)
{
    //dynamic programming function to calculate F(n)
    int result;
    if(n==0)
    {
        return 0;
    }
    if(n==1)
    {
        return 1;
    }
    if(n==2)
    {
        return 2;
    }
    else
    {
        result=dp(n-1)+dp(n-2)-2*(dp(n-3));
        return result;
    }
}

