int biggest_Component(Graph g){
    // count the number of nodes in longest component
    int count = 0;
    int temp;
    int i;
    Queue q;
    q.head = q.tail = NULL;
    q.size = 0;
    enqueue(&q, i);
    g.visited[i] = 1;
    count++;

    while(isEmptyQueue(q) == 0){
        int v;
        int stopNode;
        v = getFront(q);
        for(temp = 0; temp < g.V; temp++){
            if(g.matrix[temp][v] == 1 && g.visited[temp] == 0){
                enqueue(&q, temp);
                count++;
                stopNode = 1;
                break;
            }
        }

        if(stopNode == 0){
            removeAllItemsFromQueue(&q);
            return g.visited[temp] + 1;
        }

        for (temp = 0; temp < g.V; temp++){
            g.visited[temp] = 0;
            return 0;
            }
    }    

    return count;

}


