        for k in range(N+1):
            for i in range(N+1):
                for j in range(N+1):
                    d[i][j] = min(d[i][j], d[i][k] + d[k][j])
        return d

    N, M = MI()
    dist_ij = [[INF]*(N+1) for _ in range(N+1)]


    for _ in range(M):
        a, b, c = MI()
        a -= 1
        b -= 1
        dist_ij[a][b] = min(c, dist_ij[a][b])
        dist_ij[b][a] = min(c, dist_ij[b][a])

