        dist_ij[i][i] = 0
    for di in D:
        dist_ij[di][N] = T
        dist_ij[N][di] = 0

    dist_ij = warshall_floyd(dist_ij)


    def culc_sum():
        dist_sum = 0
        for i in range(N-1):
            for j in range(i+1, N):
                if dist_ij[i][j] != INF:
                    dist_sum += dist_ij[i][j] * 2
        return dist_sum

    def add_edge(a, b, t):
        if dist_ij[a][b] <= t:
            return

        dist_ij[a][b] = t
        for i in range(N+1):
