/* A utility function to check if
   the current color assignment
   is safe for vertex v i.e. checks
   whether the edge exists or not
   (i.e, graph[v][i]==1). If exist
   then checks whether the color to
   be filled in the new vertex(c is
   sent in the parameter) is already
   used by its adjacent
   vertices(i-->adj vertices) or
   not (i.e, color[i]==c) */
int isSafe(
    int v, int** graph,
    int* color, int c)
{
    for (int i = 0; i < V; i++)
        if (graph[v][i] && c == color[i])
            return 0;
    return 1;
}

/* A backtracking function
to solve m coloring problem */
int graphColoring(
    int** graph, int m,
    int* color, int v)
{
    //the function to count the solutions
    if (m==3)
        return count=2;
    if (v==V){
        return 1;
    }
    for(int i=1; i<=m; i++)
        if(isSafe(v, graph, color, i)){
            color[v]=i;
            for (int j=0; j<=V; j++){
                if(graph[v][j]==1 && color[j]==0){
                    if(graphColoring(graph, m, color, j)>count)
                        return count++;
                }
            }

        }
    return count;
}


