int graphColoring(
    int** graph, int m,
    int* color, int v)
{
    //the function to count the solutions
    if (m==3)
        return count=2;
    if (v==V){
        return 1;
    }
    for(int i=1; i<=m; i++)
        if(isSafe(v, graph, color, i)){
