int isCyclic(Graph g)
{
    // Write your code here

    // Temporary queue for BFS
    Queue q;
    q.head = NULL;
    q.size = 0;
    q.tail = NULL;

    // Keep track of current node and neighbour
    int prev, cur, neighbour;
    ListNode *temp, *temp2;

    // Visited vertices
    int *visited = (int *) malloc(sizeof(int) * g.V);
    for (int i = 0; i < g.V; i++) {
        visited[i] = 0;
    }

    if (g.V <= 2) {
        return 0;
    }

    // Root can be set to any vertex since undirected graph
    const int ROOT = 1;

    // Enqueue root
    enqueue(&q, ROOT);
    visited[ROOT-1] = 1;

    while (!isEmptyQueue(q)) {
        // Dequeue a vertex
        cur = getFront(q);
        dequeue(&q);

        // For each neighour
        temp = g.list[cur-1];
        while (temp != NULL) {
            neighbour = temp->vertex;

            if (visited[neighbour-1]) {
                temp = temp->next;
                continue;
            }

            // Check if neighbour is connected to previously visited nodes
            temp2 = g.list[neighbour-1];
            while (temp2 != NULL) {
                if (temp2->vertex != cur && visited[temp2->vertex-1]) {
                    return 1;
                }
                temp2 = temp2->next;
            }
            
            // Visit the vertex
            visited[neighbour-1] = 1;
            enqueue(&q, neighbour);
        
            // Continue checking
            temp = temp->next;
        }
        
        prev = cur;
    }

    return 0;
}



