int isCyclic(Graph g) {
  // Write your code here

  Queue q;
  q.head = NULL;
  q.size = 0;
  q.tail = NULL;
  int sum = 0;
  int i;
  int vertex = 1;
  int visited[g.V];
  for (i = 0; i < g.V; i++) {
    visited[i] = 0;
  }

  visited[vertex -1 ] = 1;
  enqueue(&q, vertex);
  sum+= 1;

  
  while (!isEmptyQueue(q)) {
    vertex = dequeue(&q);
    ListNode *temp;
    temp = g.list[vertex -1 ];
    while (temp != NULL) {
      if (visited[temp->vertex - 1] == 0) {
        visited[temp->vertex - 1] = 1;
        enqueue(&q, (temp->vertex - 1));
        sum += 1;
      }
      temp = temp->next;
    }
  }

  if (sum >= g.V) {
    return 1;
  }

