int dp(int n)
{
    //dynamic programming function to calculate F(n)

    int i;
    int *F;
    F = malloc(sizeof(int));
    for(i=0;i<n+3;i++){
       F[i]=0;
}
    //F[n+3] = malloc(sizeof(int)*(n+3));

    F[1] = 1;
    F[0] = 0;
