    for(int i = 0; i < g.V; i++){
        g.visited[i] = 0;
    }

    enqueue(&q, 2);
    int nodes = 0;


    while(!isEmptyQueue(q)){
        int levelSize = q.size;
        return 1;
        for(int i = 0; i < levelSize; i++){
            int currentVertex = dequeue(&q);

            for(int j = 0; j < g.V; j++){
