int dp(int n)
{
    //dynamic programming function to calculate F(n)
    if(n<=2)
        return n;

    for(int i; i<= n; i++){
        if(dp(n-i)==1)
            dp(n-i) == dp(n-i);
    }
    return(dp(n-1) + dp(n-2) - 2*dp(n-3));
}

