int isCyclic(Graph g)
{
 // Write your code here
    // DFS
    Stack S;
    int g_visited[g.V + 1]; // vertice 1 at index 1
    int w;
    ListNode* temp;
    int exit_vertex = 0;
    int enter_vertex = 0;

    // go through all vertices to check whether go out and in through the same route
    // if there is one vertice able to go out and in through different route, it is a cyclic, else, acyclic
    for (int i = 1; i <= g.V; i++)
    {
        S.head = NULL;
        S.size = 0;
        
        for (int j = 0; j <= g.V; j++) g_visited[j] = 0;
        
        exit_vertex = 0;
        enter_vertex = 0;
        
        push(&S, i); // vertice not marked visited, check if when visited, whether exitroute and enterroute is the same
        exit_vertex = g.list[i-1]->vertex;
        
        while(!isEmptyStack(S))
        {
            w = peek(S);
            temp = g.list[w-1];
            while(temp!=NULL)
            {
                if (g_visited[temp->vertex] == 0)
                {
                    push(&S, temp->vertex);
                    g_visited[temp->vertex] = 1;
                    if (temp->vertex == i)
                    {
                        enter_vertex = w;
                        if(enter_vertex != exit_vertex) return 1;
                    }
                    break;
                }
                temp = temp->next;
            }
            if(temp == NULL) pop(&S);
        }
        
    }
    return 0;
}



