int isCyclic(Graph g)
{
    // Write your code here
    // initialise queue -- BFS
    ListNode *temp;
    temp->next = NULL;
    temp->vertex = 0;
    Queue q;
    q.head = NULL;
    q.tail = NULL;
    q.size = 0;
    // create array to keep track of visited vertices
    int visited[g.V];
    int j,w;
    int count = 0;

    for (int i = 0; i < g.V; i++){
        visited[i] = -1;
    }

    // if graph is empty
    if (g.V == 0)
        return 0;
    // loop through all vertex
    for (j = 1; j <= g.V; j++){
        // enqueue 1st vertex
        enqueue(&q, j);
        visited[j-1] = 1;

        // check adjacent vertices
        while (!isEmptyQueue(q)){
            w = dequeue(&q);
            int cut = 0;
            for (int i = 1; i <= g.V; i++){
                // check adjL for adjacent vertices
                temp = g.list[w-1];
                while (temp->next != NULL){
                    int r = temp->next->vertex;
                    if (r != 0){
                        if (visited[r -1] == 1){
                            if (r == i)
                                count++;
                            temp = temp->next;
                        }
                        else {
                            enqueue(&q, i);
                            visited[i-1] = 1;
                            cut = 1;
                            break;
                        }
                    }
                }
                
                // break for loop for adjacent vertex
                if (cut != 0)
                    continue;

            }
        }
    // check count
    if (count == g.V){
        // all vertices are cyclic
        return 1;
    }


    return 0;
}

}



