int isCyclic(Graph g)
{
    int i, j, temp, unvisit, times;
    ListNode *tempNode;
    int *visit;
    Stack s;

    for (i = 0; i < g.V; i++)
    {
        times = 0;
        s.head = NULL;
        s.size = 0;

        visit = (int *)malloc(g.V * sizeof(int));

        for (j = 0; j < g.V; j++)
            visit[j] = 0;

        push (&s, i+1);
        visit[i] = 0;
        while (!isEmptyStack(s))
        {
            temp = peek(s);
            unvisit = 0;
            tempNode = g.list[temp-1];
            while (tempNode)
            {
                if (tempNode->vertex - 1 == i)
                {
                    while (!isEmptyStack(s))
                    {
                        pop(&s);
                        times++;
                    }
                    if (times > 2)
                        return 1;
                    else 
                    {
                        unvisit = 1;
                        break;
                    }
                }
                else if (visit[tempNode->vertex-1] == 0)
                {
                    push(&s, tempNode->vertex);
                    visit[tempNode->vertex - 1] = 1;
                    unvisit = 1;
                    tempNode = tempNode->next;
                    break;
                }
            }
            if (unvisit == 0)
            {
                pop(&s);
            }
        }
    }
    return 0;
}



