    if(v==V){
        count=count+2;
        return 0;
    }

    for (int c=1; c<=m; c++){
        if(isSafe(v,graph,color,c)){
            color[v]=c;
        }
    }
    graphColoring(graph, m, color, v + 1);
    color[v]=0;

    return 0;
}


