        for j in range(n+1):
            if d[i][j] > d[i][k] + d[k][j]:
                d[i][j] = d[i][k] + d[k][j]

for i in range(n-1):
    for j in range(i+1, n):
        if d[i][j] < INF: total_time += d[i][j]
total_time *= 2

