int dp(int n)
{
    //dynamic programming function to calculate F(n)
    int a= 0;
    int b = 1;
    int c = 2;
    for(int i = 3; i<=n;i++)
    {
        int temp = c;
        c= c+2 * b-3 * a;
        a = b;
        b = temp;
    }
    return 3;
}

